```javascript
class MyListComponent extends HTMLElement {
  constructor() {
    super();
    this._data = [];
  }

  set data(value) {
    this._data = value;
    this.render();
  }

  get data() {
    return this._data;
  }

  connectedCallback() {
    this.render();
  }

  render() {
    if (!this._data.length) return;
    this.innerHTML = `<ul>${this._data.map(item => `<li>${item.name}</li>`).join('')}</ul>`;
